package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.articles.CatalogVersionQualificationService;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.node.ObjectNode;

/** Real owned qualification reads. External sender and reference admission remain the original fictional ports. */
class CatalogVersionQualificationProjectionTest extends CatalogVersionQualificationTest {
    CatalogVersionQualificationProjection.Projection projection(){return service.readProjection(f.category,"fictional-entity","fictional-analysis","fictional-current-item",f.clock.instant()).orElseThrow();}
    @Test void FourCategoryCompactProofKeepsExactOriginalNativeClaimAndBothCompleteVersionRefs(){for(String category:List.of("agent","skill","workflow","model")){initialize(category,false);var selection=read().orElseThrow();var p=projection();assertTrue(p.versionChanged());assertEquals(selection.previous().proofHash(),p.resultConstraint().previousProofHash());assertEquals(selection.currentProofHash(),p.resultConstraint().newProofHash());assertEquals(p.hash(),CanonicalJson.hash(CanonicalJson.Domain.INPUT,p.toJson()));assertEquals("fictional-current-item",p.memberId());var raw=p.toJson();assertEquals(f.identity.inputHash(),raw.get("input_hash").asText());var claim=tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("root_id",f.identity.rootId()).put("attempt_id",f.identity.attemptId()).put("dispatch_token",f.identity.fencing()).put("slot_revision",f.identity.slotRevision());assertEquals(JdbcResultState.sha(JdbcFrozenInputs.canonical(claim)),p.claimTargetHash());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='worker_claim' AND target_key_hash=?",Integer.class,HexFormat.of().parseHex(p.claimTargetHash())));assertTrue(p.json().getBytes(StandardCharsets.UTF_8).length<=CatalogVersionQualificationProjection.MAX_BYTES);var copy=(ObjectNode)p.toJson();copy.put("entity_generation",99);assertEquals(1,p.toJson().get("entity_generation").asLong());assertFalse(p.toString().contains("fictional"));assertEquals(1,f.sends);}}
    @Test void HundredLargeOriginalBodiesBecomeACompleteBoundedProjectionWithoutRetainingPayloadObjects(){var large=new CatalogPreviousVersionProfileTest.Fixture(){@Override ObjectNode catalogPayload(){return super.catalogPayload().put("summary","Fictional large original body "+"x".repeat(8000));}};large.members=100;large.initializeCatalog(mysql(),"agent",true);f=large;current=f.catalogPayload();current.put("version","v2");((ObjectNode)current.get("evidence").get(0)).put("revision","v2");f.jdbc.update("INSERT INTO source_run_items VALUES('fictional-current-item','fictional-run','fictional-source',3,'agent',?,'accepted','pending','initialized',1,?,?,NULL,'fictional-current-source-item')",java.sql.Timestamp.from(f.clock.instant().minusSeconds(1)),JdbcFrozenInputs.canonical(current),HexFormat.of().parseHex(CatalogPreviousAnalysisTest.Fixture.sha(CanonicalJson.bytes(current))));service=new CatalogVersionQualificationService(f.source,f.tx);var previous=read().orElseThrow().previous().evidence().previous();assertTrue(previous.inputJson().getBytes(StandardCharsets.UTF_8).length>800000);var p=projection();assertEquals(100,p.toJson().get("previous_proof").get("members").size());assertTrue(p.json().contains("fictional-item-99"));assertFalse(p.json().contains("Fictional large original body"));assertTrue(p.json().getBytes(StandardCharsets.UTF_8).length<65536);for(var field:p.getClass().getDeclaredFields())assertTrue(field.getType()==String.class||field.getType()==boolean.class,field.getName());assertEquals(1,f.sends);}
    @Test void SameVersionIdentitySurvivesMetadataLaterEntityGenerationAndDatesButSemanticOrDefinitionChanges(){var p=projection();current.put("summary","Fictional later summary");update();f.jdbc.update("UPDATE analyzed_entities SET revision=revision+1,analysis_generation=2,analysis_state='failed'");var next=service.readProjection(f.category,"fictional-entity","fictional-analysis","fictional-current-item",f.clock.instant().plusSeconds(1)).orElseThrow();assertEquals(p.judgmentKey(),next.judgmentKey());assertNotEquals(p.hash(),next.hash());current.put("version","v3");((ObjectNode)current.get("evidence").get(0)).put("revision","v3");update();assertNotEquals(p.judgmentKey(),projection().judgmentKey());initialize("agent",false);f.jdbc.update("UPDATE source_runs SET config_snapshot_json=?","{\"parser_version\":\"fictional-parser-v1\",\"fictional_definition\":2}");assertNotEquals(p.judgmentKey(),projection().judgmentKey());current.putNull("version");update();assertTrue(service.readProjection(f.category,"fictional-entity","fictional-analysis","fictional-current-item",f.clock.instant()).isEmpty());}
}
